<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { api } from '../services/api'

const rows=ref([]),q=ref(''),category=ref('All'),status=ref('All'),showAdd=ref(false),showImport=ref(false),credential=ref(null),csv=ref('')
const form=reactive({name:'',email:'',phone:'',company:'',category:'General',status:'Pending',event_id:'evt_001'})
const categories=['All','General','VIP','Sponsor','Speaker','Media']
const statuses=['All','Confirmed','Pending','Waitlist','Rejected']

onMounted(load)
async function load(){rows.value=await api.attendees()}
const filtered=computed(()=>rows.value.filter(x=>(category.value==='All'||x.category===category.value)&&(status.value==='All'||x.status===status.value)&&(x.name+x.company+x.id+x.email).toLowerCase().includes(q.value.toLowerCase())))
async function add(){const row=await api.createAttendee(form);rows.value.unshift(row);showAdd.value=false;Object.assign(form,{name:'',email:'',phone:'',company:'',category:'General',status:'Pending',event_id:'evt_001'})}
async function setStatus(row,next){const updated=await api.updateAttendee(row.id,{status:next});Object.assign(row,updated)}
async function importCsv(){await api.importAttendees(csv.value);showImport.value=false;csv.value='';await load()}
async function showCredential(row){credential.value=await api.credential(row.id)}
function exportCsv(){window.location.assign('/api/v1/attendees/export')}
</script>
<template><div class="space-y-6">
<section class="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="eyebrow">People</p><h1 class="page-title">Attendees <span class="text-slate-400">({{rows.length}})</span></h1><p class="page-subtitle">Create, approve, import, export and issue signed event credentials.</p></div><div class="flex flex-wrap gap-2"><button class="btn-secondary" @click="showImport=true">Import CSV</button><button class="btn-secondary" @click="exportCsv">Export CSV</button><button class="btn-primary" @click="showAdd=true">+ Add Attendee</button></div></section>
<section class="panel overflow-hidden"><div class="grid gap-3 border-b border-slate-100 p-4 sm:grid-cols-[1fr_160px_160px]"><input v-model="q" class="control" placeholder="Search by name, email, ticket ID…"/><select v-model="category" class="control"><option v-for="c in categories" :key="c">{{c}}</option></select><select v-model="status" class="control"><option v-for="s in statuses" :key="s">{{s}}</option></select></div><div class="overflow-x-auto"><table class="data-table"><thead><tr><th>Name</th><th>Category</th><th>Company</th><th>Ticket ID</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td><div class="flex items-center gap-3"><div class="grid h-9 w-9 place-items-center rounded-full bg-indigo-50 text-xs font-bold text-indigo-700">{{r.initials}}</div><div><b>{{r.name}}</b><p>{{r.email}}</p></div></div></td><td><span class="soft-pill">{{r.category}}</span></td><td>{{r.company}}</td><td class="font-mono text-xs">{{r.id}}</td><td><span class="status-badge" :class="r.status==='Confirmed'?'badge-published':'badge-draft'">{{r.status}}</span></td><td><div class="flex gap-1"><button v-if="r.status!=='Confirmed'" class="icon-btn" title="Approve" @click="setStatus(r,'Confirmed')">✓</button><button v-if="r.status==='Pending'" class="icon-btn" title="Reject" @click="setStatus(r,'Rejected')">×</button><button class="icon-btn" title="Credential" @click="showCredential(r)">▦</button></div></td></tr></tbody></table></div></section>
<div v-if="showAdd" class="modal-backdrop" @click.self="showAdd=false"><form class="modal-card" @submit.prevent="add"><h2 class="text-lg font-bold">Add attendee</h2><div class="mt-5 grid gap-4"><label class="field"><span>Name</span><input v-model="form.name" required/></label><label class="field"><span>Email</span><input v-model="form.email" type="email" required/></label><label class="field"><span>Company</span><input v-model="form.company"/></label><label class="field"><span>Category</span><select v-model="form.category"><option v-for="c in categories.slice(1)" :key="c">{{c}}</option></select></label></div><div class="mt-6 flex justify-end gap-2"><button type="button" class="btn-secondary" @click="showAdd=false">Cancel</button><button class="btn-primary">Create</button></div></form></div>
<div v-if="showImport" class="modal-backdrop" @click.self="showImport=false"><div class="modal-card"><h2 class="text-lg font-bold">Import attendees</h2><p class="mt-2 text-xs text-slate-500">Paste CSV with headers such as name,email,company,category,status.</p><textarea v-model="csv" class="control mt-4 min-h-48 font-mono text-xs" placeholder="name,email,company,category&#10;Jane Doe,jane@example.com,Acme,VIP"></textarea><div class="mt-6 flex justify-end gap-2"><button class="btn-secondary" @click="showImport=false">Cancel</button><button class="btn-primary" @click="importCsv">Import</button></div></div></div>
<div v-if="credential" class="modal-backdrop" @click.self="credential=null"><div class="modal-card"><p class="panel-kicker">Signed credential</p><h2 class="mt-2 text-lg font-bold">{{credential.attendee_id}}</h2><p class="mt-3 break-all rounded-xl bg-slate-950 p-4 font-mono text-[10px] leading-5 text-cyan-200">{{credential.payload}}</p><p class="mt-3 text-xs text-slate-500">This signed payload is ready for the QR renderer and Phase 2 scanner.</p><button class="btn-secondary mt-5 w-full" @click="credential=null">Close</button></div></div>
</div></template>
